// Proppr Lead Data Normalization & Currency Parser
const raw = $json.body || $json;

// 1. Phone Normalization (Indian 10-digit standard)
let phone = (raw.phone_number || raw.phone || '').toString().replace(/\D/g, '');
if (phone.length === 12 && phone.startsWith('91')) phone = phone.substring(2);
if (phone.length === 11 && phone.startsWith('0')) phone = phone.substring(1);

// 2. Budget Parser (Handles ₹ Cr, Lakhs, numerical)
function parseBudget(budgetStr) {
  if (!budgetStr) return 0;
  if (typeof budgetStr === 'number') return budgetStr;
  const str = budgetStr.toString().toLowerCase();
  const match = str.match(/(\d+(?:\.\d+)?)/);
  if (!match) return 0;
  const val = parseFloat(match[1]);
  if (str.includes('cr') || str.includes('crore')) return val * 10000000;
  if (str.includes('lakh') || str.includes('lac') || str.includes('l')) return val * 100000;
  return val;
}

const budgetInr = parseBudget(raw.budget);
const location = (raw.location || '').trim();
const isGurgaon = location.toLowerCase() === 'gurgaon';
const isPriority = isGurgaon && (budgetInr >= 15000000);

return {
  lead_id: raw.lead_id || Date.now(),
  name: (raw.name || 'Valued Lead').trim(),
  phone_number: phone,
  raw_phone: raw.phone_number,
  location: location || 'Unspecified',
  budget_raw: raw.budget || 'Not provided',
  budget_inr: budgetInr,
  source: raw.source || 'Website',
  enquiry_date: raw.enquiry_date || new Date().toISOString(),
  is_priority: isPriority,
  priority_tag: isPriority ? 'HIGH PRIORITY (Gurgaon >= ₹1.5 Cr)' : 'STANDARD',
  assigned_desk: isGurgaon ? (isPriority ? 'Gurgaon Senior Advisory' : 'Gurgaon Residential') : (location.toLowerCase() === 'goa' ? 'Goa Luxury Desk' : 'General Sales'),
  ingested_at: new Date().toISOString()
};

